// @asaidimu/anansi — self-contained TypeScript implementation of the
// Anansi binary wire format: schema compile/link/addressing, packet codecs,
// transforms, validation, and migrations.

// Auto-generated schema types (regenerated by `anansi codegen typescript`).
// Wholesale re-export is deliberate: cherry-picking would rot every time the
// meta schema gains a type — the set is defined by generated.ts, not here.
export * from "./schema/types.ts";
export { Compiler, buildEnum } from "./schema/compile.ts";
export type {
  ResolvedField, ResolvedNested, ResolvedEnum,
} from "./schema/compile.ts";
export type {
  ManifestField, LinkResult, LinkedField, LinkedSlot,
  FieldDescriptor, Slot,
} from "./schema/link.ts";
export {
  link, makeDescriptor, unpackDescriptor, internalDP,
  addressForSteps, userDataDP, buildManifest,
  FD_NO_CHILD, MAX_SCHEMA_SLOTS, MULTI_STEP_BASE,
} from "./schema/link.ts";
export { container as DataTypes } from "./schema/dt.ts";

// Schema helpers — hydrate/defaults/empty/pick/required + memoized validator.
export { SchemaUtil } from "./schema/util.ts";

// Error vocabulary: registered SystemError codes shared by every subsystem,
// plus the builder and the package predicate.
export { AnansiCodes, anansiError, isAnansiError, SystemError } from "./errors.ts";
export type { AnansiCode } from "./errors.ts";

export {
  encodeDocument, decodeDocument,
  encodeBatchRows, encodeBatchColumnar, decodeBatch,
} from "./wire/packet.ts";
export type { EncodeKind } from "./wire/packet.ts";

// Friendly facade — one object per schema, cached by the consumer.
export { AnansiCodec } from "./codec.ts";
export type { AnansiCodecOptions } from "./codec.ts";

// Migration types: schema changes, data transforms, migrations, version bumping.
export type {
  SchemaChange,
  Migration,
  DataTransform,
  TransformFunction,
  ChangeImpact,
  FieldPatch,
  ConstraintPatch,
  IndexPatch,
  Patch,
  PatchOp,
} from "./migration/migration.ts";
export {
  classifyChangeImpact,
  calculateNextBump,
  bumpVersion,
  schemaChangeToPatch,
} from "./migration/migration.ts";

// Semantic versions — parse/compare/bump, 64-bit bitfield packing, tag
// ranking (alpha/beta/rc), history addressing, Versionable lifecycle.
// Implementation lives in @asaidimu/utils-version; re-exported here so the
// package's public API is unchanged.
export {
  Version, VersionRegistry, Versionable,
  parseVersion, sortVersions, latest,
  newHistoryAddress, decodeHistoryAddress,
  historyAddressToAbsolute, absoluteToHistoryAddress,
  configureVersioning, getDefaultRegistry,
  RankNone, RankStable, MaxHistorySize,
  ErrAlreadyConfigured, ErrHistoryFull, ErrInvalidAddress,
  ErrNotPrerelease, ErrAlreadyStable, ErrVersionNotFound,
  VersionCodes, versionError,
} from "@asaidimu/utils-version";
export type {
  TagRank, VersionStrategy, VersionableJSON, VersionCode,
} from "@asaidimu/utils-version";

// Migration engine — schema versioning, dry-run, rollback, checksums.
export { MigrationEngine } from "./migration/engine.ts";
export type { EngineState, DryRunResult } from "./migration/engine.ts";

// Utilities.
export { deepMerge, sha256 } from "./utils.ts";

// Validation (adopted validator): documents against schemas, and schemas
// against the meta-schema. Re-exported wholesale so additions to
// ./validation/index.ts become public automatically — do not cherry-pick
// here, a forgotten entry silently drops the export from the published
// bundle (previously lost StandardDocumentValidator).
export * from "./validation/index.ts";

// Transforms (compression / integrity / encryption) — async, browser-safe.
export {
  encodeAnansiPacket, decodeAnansiPacket,
  encodeAnansiBatchRows, encodeAnansiBatchColumnar, decodeAnansiBatch,
  FLAG_COMPRESSED, FLAG_ENCRYPTED, FLAG_HASH_PRESENT,
} from "./wire/transforms.ts";
export type { EncodeTransforms, DecodeTransforms } from "./wire/transforms.ts";
